def parse_sku_line(line):
    """解析 "sku,数量" 行：拆分并去除字段空白，返回 (sku, qty_str)。"""
    sku, qty = line.split(",")
    return (sku, qty)

verification_tests:
from target import parse_sku_line

def test_clean_line():
    assert parse_sku_line("A1,5") == ("A1", "5")

def test_spaced_line():
    assert parse_sku_line("A1, 5") == ("A1", "5")

def test_surrounding_space():
    assert parse_sku_line(" A1 ,5 ") == ("A1", "5")
